@push('scripts')<script>const accountType=document.querySelector('#account-type');const accountName=document.querySelector('#account-name');const customName=document.querySelector('#custom-account-name');function toggleCustom(){customName.hidden=accountName.value!=='custom';if(accountName.value==='custom'){accountType.value='custom';}}accountName.addEventListener('change',toggleCustom);accountType.addEventListener('change',function(){if(this.value==='cash'){accountName.value='Cash';}else if(this.value==='e_wallet'){accountName.value='DANA';}else if(this.value==='custom'){accountName.value='custom';}else if(this.value==='bank'&&['Cash','custom','DANA','OVO','GoPay','ShopeePay'].includes(accountName.value)){accountName.value='BCA';}toggleCustom();});toggleCustom();</script>@endpush
